115	async fn open_sqlite(path: &Path) -> anyhow::Result<SqlitePool> {
116	    let options = SqliteConnectOptions::new()
117	        .filename(path)
118	        .create_if_missing(true)
119	        .journal_mode(SqliteJournalMode::Wal)
120	        .synchronous(SqliteSynchronous::Normal)
121	        .busy_timeout(Duration::from_secs(5))
122	        .log_statements(LevelFilter::Off);
123	    let pool = SqlitePoolOptions::new()
124	        .max_connections(5)
125	        .connect_with(options)
126	        .await?;
127	    MIGRATOR.run(&pool).await?;
128	    Ok(pool)
129	}
130	
131	pub fn state_db_filename() -> String {
132	    format!("{STATE_DB_FILENAME}_{STATE_DB_VERSION}.sqlite")
133	}
134	
135	pub fn state_db_path(codex_home: &Path) -> PathBuf {
136	    codex_home.join(state_db_filename())
137	}
138	
139	async fn remove_legacy_state_files(codex_home: &Path) {
140	    let current_name = state_db_filename();
141	    let mut entries = match tokio::fs::read_dir(codex_home).await {
142	        Ok(entries) => entries,
143	        Err(err) => {
144	            warn!(
145	                "failed to read codex_home for state db cleanup {}: {err}",
146	                codex_home.display()
147	            );
148	            return;
149	        }
150	    };
151	    while let Ok(Some(entry)) = entries.next_entry().await {
152	        if !entry
153	            .file_type()
154	            .await
155	            .map(|file_type| file_type.is_file())
156	            .unwrap_or(false)
157	        {
158	            continue;
159	        }
160	        let file_name = entry.file_name();
161	        let file_name = file_name.to_string_lossy();
162	        if !should_remove_state_file(file_name.as_ref(), current_name.as_str()) {
163	            continue;
164	        }
165	
166	        let legacy_path = entry.path();
167	        if let Err(err) = tokio::fs::remove_file(&legacy_path).await {
168	            warn!(
169	                "failed to remove legacy state db file {}: {err}",
170	                legacy_path.display()
171	            );
172	        }
173	    }
174	}
175	
176	fn should_remove_state_file(file_name: &str, current_name: &str) -> bool {
177	    let mut base_name = file_name;
178	    for suffix in ["-wal", "-shm", "-journal"] {
179	        if let Some(stripped) = file_name.strip_suffix(suffix) {
180	            base_name = stripped;
181	            break;
182	        }
183	    }
184	    if base_name == current_name {
185	        return false;
186	    }
187	    let unversioned_name = format!("{STATE_DB_FILENAME}.sqlite");
188	    if base_name == unversioned_name {
189	        return true;
190	    }
191	
192	    let Some(version_with_extension) = base_name.strip_prefix(&format!("{STATE_DB_FILENAME}_"))
193	    else {
194	        return false;
195	    };
196	    let Some(version_suffix) = version_with_extension.strip_suffix(".sqlite") else {
197	        return false;
198	    };
199	    !version_suffix.is_empty() && version_suffix.chars().all(|ch| ch.is_ascii_digit())
200	}
