4216	    pub async fn drop_memories(sess: &Arc<Session>, config: &Arc<Config>, sub_id: String) {
4217	        let mut errors = Vec::new();
4218	
4219	        if let Some(state_db) = sess.services.state_db.as_deref() {
4220	            if let Err(err) = state_db.clear_memory_data().await {
4221	                errors.push(format!("failed clearing memory rows from state db: {err}"));
4222	            }
4223	        } else {
4224	            errors.push("state db unavailable; memory rows were not cleared".to_string());
4225	        }
4226	
4227	        let memory_root = crate::memories::memory_root(&config.codex_home);
4228	        if let Err(err) = tokio::fs::remove_dir_all(&memory_root).await
4229	            && err.kind() != std::io::ErrorKind::NotFound
4230	        {
4231	            errors.push(format!(
4232	                "failed removing memory directory {}: {err}",
4233	                memory_root.display()
4234	            ));
4235	        }
4236	
4237	        if errors.is_empty() {
4238	            sess.send_event_raw(Event {
4239	                id: sub_id,
4240	                msg: EventMsg::Warning(WarningEvent {
4241	                    message: format!(
4242	                        "Dropped memories at {} and cleared memory rows from state db.",
4243	                        memory_root.display()
4244	                    ),
4245	                }),
4246	            })
4247	            .await;
4248	            return;
4249	        }
4250	
4251	        sess.send_event_raw(Event {
4252	            id: sub_id,
4253	            msg: EventMsg::Error(ErrorEvent {
4254	                message: format!("Memory drop completed with errors: {}", errors.join("; ")),
4255	                codex_error_info: Some(CodexErrorInfo::Other),
4256	            }),
4257	        })
4258	        .await;
4259	    }
