4261	    pub async fn update_memories(sess: &Arc<Session>, config: &Arc<Config>, sub_id: String) {
4262	        let session_source = {
4263	            let state = sess.state.lock().await;
4264	            state.session_configuration.session_source.clone()
4265	        };
4266	
4267	        crate::memories::start_memories_startup_task(sess, Arc::clone(config), &session_source);
4268	
4269	        sess.send_event_raw(Event {
4270	            id: sub_id.clone(),
4271	            msg: EventMsg::Warning(WarningEvent {
4272	                message: "Memory update triggered.".to_string(),
4273	            }),
